package com.shopsphere;
import java.math.BigDecimal;import java.util.*;import org.springframework.http.HttpStatusCode;import org.springframework.web.client.RestClient;
public interface ProductPricingGateway{Snapshot get(UUID productId);record Snapshot(UUID productId,String name,String imageUrl,BigDecimal currentPrice){}}
class HttpProductPricingGateway implements ProductPricingGateway{private final RestClient client;HttpProductPricingGateway(RestClient c){client=c;}public Snapshot get(UUID id){try{var p=client.get().uri("/api/products/{id}",id).retrieve().onStatus(HttpStatusCode::isError,(q,r)->{throw new BusinessException("Product is unavailable");}).body(ProductResponse.class);if(p==null||!p.active()||p.price()==null)throw new BusinessException("Product is unavailable");String image=p.imageUrls()==null||p.imageUrls().isEmpty()?"/media/product-fallback.svg":p.imageUrls().getFirst();return new Snapshot(p.id(),p.name(),image,p.price());}catch(BusinessException e){throw e;}catch(RuntimeException e){throw new BusinessException("Product service is temporarily unavailable");}}private record ProductResponse(UUID id,String name,BigDecimal price,List<String>imageUrls,boolean active){}}
